let x = 0;
function cuadro() {
  x = (x + 4) % 300;            // 4 px por cuadro
  caja.style.transform = `translateX(${x}px)`;
  requestAnimationFrame(cuadro);
}
requestAnimationFrame(cuadro);

const VELOCIDAD = 240;          // píxeles por segundo, en cualquier pantalla
let x = 0, antes = null;
function cuadro(ahora) {         // «ahora» llega en milisegundos
  if (antes !== null) x = (x + VELOCIDAD * (ahora - antes) / 1000) % 300;
  antes = ahora;
  caja.style.transform = `translateX(${x}px)`;
  requestAnimationFrame(cuadro);
}
requestAnimationFrame(cuadro);

// 1. Tareas largas (50 ms o más)
new PerformanceObserver((lista) => {
  for (const t of lista.getEntries()) console.log('tarea larga', Math.round(t.duration), 'ms');
}).observe({ type: 'longtask', buffered: true });

// 2. Retraso de cada interacción (Event Timing)
new PerformanceObserver((lista) => {
  for (const e of lista.getEntries()) {
    console.log(e.name, 'espera', Math.round(e.processingStart - e.startTime), 'ms');
  }
}).observe({ type: 'event', durationThreshold: 16, buffered: true });

// 3. Intervalo entre cuadros
let previo = performance.now();
function medir(ahora) {
  if (ahora - previo > 25) console.log('cuadro lento:', Math.round(ahora - previo), 'ms');
  previo = ahora;
  requestAnimationFrame(medir);
}
requestAnimationFrame(medir);
